// Thread safe.
char const * PowerCalSm_state_id_to_string(PowerCalSm_StateId id)
{
    switch (id)
    {
        case PowerCalSm_StateId_ROOT: return "ROOT";
        case PowerCalSm_StateId_AUTO: return "AUTO";
        case PowerCalSm_StateId_BAND: return "BAND";
        case PowerCalSm_StateId_BAND_DONE: return "BAND_DONE";
        case PowerCalSm_StateId_DONE: return "DONE";
        case PowerCalSm_StateId_FIT_ALL: return "FIT_ALL";
        case PowerCalSm_StateId_FIT_FORWARD: return "FIT_FORWARD";
        case PowerCalSm_StateId_POINT: return "POINT";
        case PowerCalSm_StateId_COLLECT: return "COLLECT";
        case PowerCalSm_StateId_KEYDOWN: return "KEYDOWN";
        case PowerCalSm_StateId_METER_ENTRY: return "METER_ENTRY";
        case PowerCalSm_StateId_METER_PAUSED: return "METER_PAUSED";
        case PowerCalSm_StateId_PROMPT: return "PROMPT";
        case PowerCalSm_StateId_REST: return "REST";
        case PowerCalSm_StateId_REVIEW: return "REVIEW";
        case PowerCalSm_StateId_SETUP: return "SETUP";
        case PowerCalSm_StateId_STORE: return "STORE";
        case PowerCalSm_StateId_MANUAL: return "MANUAL";
        case PowerCalSm_StateId_MEASUREMENTCOMPLETE: return "MEASUREMENTCOMPLETE";
        case PowerCalSm_StateId_POWERCOMPLETE: return "POWERCOMPLETE";
        case PowerCalSm_StateId_POWERPOINT1: return "POWERPOINT1";
        case PowerCalSm_StateId_POWERPOINT2: return "POWERPOINT2";
        case PowerCalSm_StateId_POWERPOINT3: return "POWERPOINT3";
        case PowerCalSm_StateId_SSBPOINT: return "SSBPOINT";
        default: return "?";
    }
}

// Thread safe.
